/**
 * LandingPage.tsx — Single screen, no scroll.
 * "Play IFS" fires onPlay() directly.
 * c4 (LeBron) pre-revealed with headshot. Other 5 cards clickable individually.
 */
import { useState } from "react";

// ─── card art (base64 PNG) ────────────────────────────────────────────
const CARD_BACK   = "data:image/png;base64,";
const CARD_ORANGE = "data:image/png;base64,";
const CARD_PURPLE = "data:image/png;base64,";
const CARD_BLUE   = "data:image/png;base64,";
const CARD_GREEN  = "data:image/png;base64,";
const CARD_GREY   = "data:image/png;base64,";

// ─── tokens ──────────────────────────────────────────────────────────────
const BLACK  = "#070A12";
const DARK   = "#0D1220";
const SURF   = "#111827";
const BORDER = "rgba(255,255,255,0.07)";
const TEXT   = "#F0F2F5";
const MUTED  = "rgba(240,242,245,0.38)";
const GOLD   = "#C9A84C";
const ORANGE = "#E8631A";
const PURPLE = "#8B5CF6";
const BLUE   = "#4B9EE8";
const GREEN  = "#7FFF00";

// ─── card definitions ────────────────────────────────────────────────────
type Card = {
  id: string; name: string; pos: string;
  fp: string; fpColor: string; asset: string;
  stamp?: string; stampColor?: string; spotlight?: boolean;
};

const CARDS: Card[] = [
  { id:"c1", name:"T. Young",  pos:"PG",    fp:"43.5", fpColor:BLUE,   asset:CARD_GREY   },
  { id:"c2", name:"D. Fox",    pos:"PG",    fp:"61.2", fpColor:BLUE,   asset:CARD_BLUE   },
  { id:"c3", name:"N. Jokic",  pos:"C",     fp:"68.4", fpColor:GOLD,   asset:CARD_ORANGE },
  { id:"c4", name:"L. James",  pos:"SF/PF", fp:"89.5", fpColor:GOLD,   asset:CARD_ORANGE,
    stamp:"LEGENDARY", stampColor:GOLD, spotlight:true },
  { id:"c5", name:"S. Curry",  pos:"PG",    fp:"77.8", fpColor:PURPLE, asset:CARD_PURPLE,
    stamp:"ON FIRE 🔥", stampColor:ORANGE },
  { id:"c6", name:"K. Durant", pos:"SF",    fp:"71.2", fpColor:PURPLE, asset:CARD_PURPLE,
    stamp:"ON FIRE 🔥", stampColor:ORANGE },
];

// fan: [left px, top px, rotation]
const FAN: [number, number, string][] = [
  [0,   52, "-13deg"],
  [96,  24,  "-6deg"],
  [190,  8,  "-1deg"],
  [284,  8,   "1deg"],
  [378, 24,   "6deg"],
  [474, 52,  "13deg"],
];

const LEBRON_CARD = "data:image/png;base64,";

interface Props { onPlay: () => void; }

// ─── component ───────────────────────────────────────────────────────────
export function LandingPage({ onPlay }: Props) {
  // c4 (LeBron) pre-revealed; others flip individually on tap
  const [flipped, setFlipped] = useState<Set<string>>(new Set(["c4"]));

  function toggleCard(id: string) {
    if (id === "c4") return; // LeBron is static
    setFlipped(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  }

  const CSS = `
    * { box-sizing:border-box; }
    .lp-card {
      transform-style:preserve-3d;
      border-radius:12px;
      transition:transform .55s cubic-bezier(.4,0,.2,1);
      cursor:pointer;
    }
    .lp-face,.lp-back {
      position:absolute;inset:0;
      backface-visibility:hidden;-webkit-backface-visibility:hidden;
      border-radius:12px;background-size:cover;background-position:center;
    }
    .lp-back { transform:rotateY(0deg); }
    .lp-face { transform:rotateY(180deg); }
    .lp-stamp {
      position:absolute;top:50%;left:50%;
      transform:translate(-50%,-50%) rotate(-11deg) scale(.5);
      border:2.5px solid;border-radius:4px;padding:3px 9px;
      font-weight:900;font-size:10px;letter-spacing:.18em;text-transform:uppercase;white-space:nowrap;
      opacity:0;
    }
    .lp-stamp.on { opacity:1;transform:translate(-50%,-50%) rotate(-11deg) scale(1); }
    @keyframes lp-pulse {
      0%,100% { box-shadow:0 0 0 0 rgba(127,255,0,0); }
      50%      { box-shadow:0 0 22px 7px rgba(127,255,0,.5); }
    }
    .lp-cta {
      position:relative;cursor:pointer;
      background:linear-gradient(135deg,#7FFF00 0%,#5BBE00 100%);
      color:#070A12;border:none;border-radius:2px;
      font-weight:800;letter-spacing:.12em;text-transform:uppercase;font-family:'Impact','Arial Narrow',Arial,sans-serif;
      animation:lp-pulse 2s ease-in-out infinite;
    }
    .lp-steps { display:grid;grid-template-columns:repeat(3,1fr);gap:2px; }
    .lp-step { background:#111827;padding:22px 20px;position:relative;overflow:hidden; }
    .lp-back-shine { display:none; }
    @keyframes tap-pulse {
      0%,100% { opacity:.45; }
      50%      { opacity:1; }
    }
    .lp-tap-label {
      animation:tap-pulse 1.8s ease-in-out infinite;
    }
    .lp-tap-label {
      position:absolute;bottom:18px;left:50%;transform:translateX(-50%);
      font-family:'Impact','Arial Narrow',Arial,sans-serif;font-weight:800;font-size:13px;
      letter-spacing:.22em;text-transform:uppercase;
      color:rgba(255,255,255,.55);pointer-events:none;white-space:nowrap;
    }

    @media(max-width:680px){
      .lp-fan  { width:320px !important; height:200px !important; }
      .lp-card { width:64px !important; height:91px !important; }
      .lp-steps { grid-template-columns:1fr !important; }
    }
  `;

  return (
    <div style={{
      background:BLACK, color:TEXT, fontFamily:"'Impact','Arial Narrow',Arial,sans-serif",
      height:"100dvh", maxHeight:"100dvh", overflow:"hidden",
      display:"flex", flexDirection:"column",
    }}>
      <style>{CSS}</style>

      {/* NAV */}
      <nav style={{
        flexShrink:0, display:"flex", justifyContent:"center", alignItems:"center",
        padding:"10px 32px",
        background:"rgba(7,10,18,.92)", backdropFilter:"blur(12px)",
        borderBottom:`1px solid ${BORDER}`,
      }}>
        <Logo />
      </nav>

      {/* MAIN */}
      <main style={{
        flex:1, minHeight:0,
        display:"flex", flexDirection:"column", alignItems:"center",
        justifyContent:"flex-start",
        padding:"52px 24px 10px",
        gap:0,
        textAlign:"center", overflow:"hidden",
        position:"relative",
      }}>
        {/* ambient glow */}
        <div style={{ position:"absolute",inset:0,
          background:"radial-gradient(ellipse 70% 45% at 50% 18%,rgba(75,158,232,.07),transparent 65%)",
          pointerEvents:"none" }} />

        {/* ── CARDS FAN ── */}
        <div style={{ position:"relative", flexShrink:0, zIndex:1, marginBottom:16 }}>
          <div className="lp-fan"
            style={{ position:"relative", width:640, height:255, perspective:"1200px" }}>
            {CARDS.map((c, i) => {
              const [left, top, rot] = FAN[i];
              const isFlipped = flipped.has(c.id);
              const isSpotlit = c.id === "c4";
              const flippedTransform = isSpotlit
                ? `rotate(${rot}) rotateY(180deg) translateY(-10px) scale(1.07)`
                : `rotate(${rot}) rotateY(180deg) translateY(-10px) scale(1.07)`;
              return (
                <div
                  key={c.id}
                  className="lp-card"
                  onClick={() => toggleCard(c.id)}
                  style={{
                    position:"absolute", width:120, height:171, left, top,
                    zIndex: isSpotlit ? 20 : i,
                    transform: isFlipped ? flippedTransform : `rotate(${rot})`,
                    boxShadow: isFlipped ? "0 12px 36px rgba(201,168,76,.25)" : undefined,
                    transition: isSpotlit ? "none" : undefined,
                  }}>
                  {/* back */}
                  <div className="lp-back" style={{ backgroundImage:`url(${CARD_BACK})` }}>
                    {!isSpotlit && <div className="lp-back-shine" />}
                    {!isSpotlit && <div className="lp-tap-label">TAP</div>}
                  </div>
                  {/* front — counter-rotates to match fan angle */}
                  <div className="lp-face" style={{
                    backgroundImage: isSpotlit ? `url(${LEBRON_CARD})` : `url(${c.asset})`,
                    transform:`rotateY(180deg)`,
                  }}>
                    {c.stamp && (
                      <div className={`lp-stamp${isFlipped ? " on" : ""}`}
                        style={{ borderColor:c.stampColor, color:c.stampColor }}>
                        {c.stamp}
                      </div>
                    )}
                    {!isSpotlit && (
                      <div style={{ position:"absolute",bottom:0,left:0,right:0,padding:"6px 8px 7px",
                        background:"rgba(0,0,0,.82)",borderTop:"1px solid rgba(255,255,255,.06)",
                        borderRadius:"0 0 12px 12px" }}>
                        <div style={{ fontWeight:800,fontSize:11,textTransform:"uppercase",letterSpacing:".04em" }}>{c.name}</div>
                        <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center",marginTop:2 }}>
                          <span style={{ fontSize:9,color:"rgba(255,255,255,.45)",letterSpacing:".06em" }}>{c.pos}</span>
                          <span style={{ fontWeight:900,fontSize:14,color:c.fpColor }}>{c.fp}</span>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* ── HEADLINE + CTA ── */}
        <div style={{ maxWidth:560, zIndex:1, flexShrink:0, marginTop:-8 }}>
          <p style={{ fontSize:11,fontWeight:700,letterSpacing:".35em",textTransform:"uppercase",color:GOLD,marginBottom:8 }}>
            Beta · Free to Play · No Sign-Up
          </p>
          <h1 style={{
            fontFamily:"'Impact','Arial Narrow',Arial,sans-serif",fontWeight:900,
            fontSize:"clamp(28px,4.5vw,52px)",textTransform:"uppercase",lineHeight:.95,marginBottom:10,
          }}>
            You already know who balled out.<br />
            <em style={{ color:GOLD,fontStyle:"normal" }}>Prove it.</em>
          </h1>
          <p style={{ fontSize:13,color:MUTED,lineHeight:1.5,marginBottom:16 }}>
            A new way to sports entertainment,{" "}
            <strong style={{ color:TEXT }}>INSTANT</strong> fantasy sports.
          </p>
          <div style={{ display:"flex",flexDirection:"column",alignItems:"center",gap:8 }}>
            <button className="lp-cta" onClick={onPlay} style={{ padding:"14px 52px",fontSize:16 }}>
              Play IFS
            </button>
            <span style={{ fontSize:11,color:MUTED }}>
              <span style={{ color:GREEN }}>✓</span> Skill based &nbsp;·&nbsp;
              <span style={{ color:GREEN }}>✓</span> Fantasy &nbsp;·&nbsp;
              <span style={{ color:GREEN }}>✓</span> Instant results
            </span>
          </div>
        </div>

        {/* ── HOW IT WORKS ── */}
        <div style={{ width:"100%", maxWidth:1040, flexShrink:0, zIndex:1, paddingBottom:20, marginTop:"auto" }}>
          <div className="lp-steps">
            {[
              { icon:"🃏", num:"1", title:"Pick Your Players",    desc:"6 cards, 6 athletes. Hold who you believe in." },
              { icon:"⚡", num:"2", title:"Relive History",        desc:"Real historical game logs." },
              { icon:"🏆", num:"3", title:"Collect Your Winnings", desc:"The more you know, the more you win." },
            ].map((s, i) => (
              <div key={i} className="lp-step">
                <div style={{ position:"absolute",top:-14,right:12,
                  fontFamily:"'Impact','Arial Narrow',Arial,sans-serif",fontWeight:900,fontSize:80,
                  color:"rgba(255,255,255,.025)",lineHeight:1,userSelect:"none" }}>{s.num}</div>
                <span style={{ fontSize:22,marginBottom:8,display:"block" }}>{s.icon}</span>
                <div style={{ fontFamily:"'Impact','Arial Narrow',Arial,sans-serif",fontWeight:800,fontSize:16,
                  textTransform:"uppercase",letterSpacing:".04em",color:GOLD,marginBottom:5 }}>{s.title}</div>
                <p style={{ fontSize:11,color:"rgba(240,242,245,.5)",lineHeight:1.5,margin:0 }}>{s.desc}</p>
              </div>
            ))}
          </div>
        </div>
      </main>
    </div>
  );
}

// ─── Logo ─────────────────────────────────────────────────────────────────
function Logo() {
  return (
    <div style={{ fontFamily:"'Impact','Arial Narrow',Arial,sans-serif",fontWeight:900,fontSize:22,letterSpacing:-.5,color:TEXT }}>
      Replay<span style={{ color:GOLD }}>IFS</span>
    </div>
  );
}